            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "There is no credulity so eager and blind as the credulity of covetousness, which, in its universal extent, measures the moral misery and the intellectual destitution of mankind.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "The truth was that he died from solitude, the enemy known but to few on this Earth, and whom only the simplest of us are fit to withstand. The brilliant Costaguanaro of the boulevards had died from solitude and want of faith in himself and others.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "There is no peace and no rest in the development of material interests. They have their law, and their justice. But it is founded on expediency, and is inhuman; it is without rectitude, without the continuity and the force that can be found only in a moral principal.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "History repeats itself, but the special call of an art which has passed away is never reproduced. It is as utterly gone out of the world as the song of a destroyed wild bird.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "An artist is a man of action, whether he creates a personality, invents an expedient, or finds the issue of a complicated situation.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "The Westerly Wind asserting his sway from the south-west quarter is often like a monarch gone mad, driving forth with wild imprecations the most faithful of his courtiers to shipwreck, disaster, and death.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "The East Wind, an interloper in the dominions of Westerly weather, is an impassive-faced tyrant with a sharp poniard held behind his back for a treacherous stab.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "For all that has been said of the love that certain natures (on shore) have professed to feel for it, for all the celebrations it had been the object of in prose and song, the sea has never been friendly to man. At most it has been the accomplice of human restlessness.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "Coming in from the eastward, the bright colouring of the Nore lightship marking the part of the river committed to the charge of an Admiral (the Commander-in-Chief at the Nore) accentuates the dreariness and the great breadth of the Thames Estuary.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "Then, on the slight turn of the Lower Hope Reach, clusters of factory chimneys come distinctly into view, tall and slender above the squat ranges of cement works in Grays and Greenhithe.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "Between the crowded houses of Gravesend and the monstrous red-brick pile on the Essex shore the ship is surrendered fairly to the grasp of the river.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "This stretch of the Thames from London Bridge to the Albert Docks is to other watersides of river ports what a virgin forest would be to a garden.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "Protection is the first necessity of opulence and luxury.", Author = "Joseph Conrad" },
