            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "To the destruction of what is.", Author = "Joseph Conrad" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Conrad", Text = "The cabman looked at the pieces of silver, which, appearing very minute in his big, grimy palm, symbolised the insignificant results which reward the ambitious courage and toil of a mankind whose day is short on this earth of evil.", Author = "Joseph Conrad" },
